0-8a52-45df01eff674'::uuid, 'b5b7de98-e9db-449d-8593-f59ed9a8963d'::uuid, 'Folding of rock layers', FALSE, 1),('65f4e54e-aaa8-4949-8e54-a662201ad780'::uuid, 'b5b7de98-e9db-449d-8593-f59ed9a8963d'::uuid, 'Glacial carving', FALSE, 2),('0651be47-db6f-4c35-8a81-97132a7ba624'::uuid, 'b5b7de98-e9db-449d-8593-f59ed9a8963d'::uuid, 'Sedimentary deposition', FALSE, 3),('a4263c6d-5f25-4e1b-808f-f9d0d17b5770'::uuid, '8261b0bf-6202-4478-8e20-606041034a4f'::uuid, 'Benguela', TRUE, 0),('d77401cd-ff69-4254-8598-da796d273a76'::uuid, '8261b0bf-6202-4478-8e20-606041034a4f'::uuid, 'Gulf Stream', FALSE, 1),('187a168f-9fc3-4ed3-898b-79dc39f3dcc2'::uuid, '8261b0bf-6202-4478-8e20-606041034a4f'::uuid, 'Labrador', FALSE, 2),('028b893a-aa19-4300-8afa-ae4b73b45070'::uuid, '8261b0bf-6202-4478-8e20-606041034a4f'::uuid, 'Kuroshio', FALSE, 3),('70a6365a-87a8-49e1-8447-28930cfc54a5'::uuid, '88256b4b-efdf-4031-8563-0d7a0de912cc'::uuid, 'Mediterranean Sea and the Sahara Desert', TRUE, 0),('a202a971-0a37-4b30-8fec-c6c144d606df'::uuid, '88256b4b-efdf-4031-8563-0d7a0de912cc'::uuid, 'Atlantic Ocean and the Indian Ocean', FALSE, 1),('e3283668-709c-4555-8e6a-fca0355530e0'::uuid, '88256b4b-efdf-4031-8563-0d7a0de912cc'::uuid, 'Red Sea and the Atlantic Ocean', FALSE, 2),('10e0d172-d581-46cc-86dd-7ceb261f00d8'::uuid, '88256b4b-efdf-4031-8563-0d7a0de912cc'::uuid, 'Mediterranean Sea and the Kalahari Desert', FALSE, 3),('b3278ea9-bf51-4492-884b-4d6450b7ecde'::uuid, '01dbfc8f-dc91-4c8f-8208-30ba6a29b103'::uuid, 'Eurasian Plate', TRUE, 0),('bd63fe05-d1a9-42d5-86ad-93c739c626f8'::uuid, '01dbfc8f-dc91-4c8f-8208-30ba6a29b103'::uuid, 'African Alpine System', FALSE, 1),('cb7dd0d6-a398-4bdc-853e-b00ba7a3eb52'::uuid, '01dbfc8f-dc91-4c8f-8208-30ba6a29b103'::uuid, 'African massif', FALSE, 2),('a0280936-ff9d-4856-8354-a23743b8908a'::uuid, '01dbfc8f-dc91-4c8f-8208-30ba6a29b103'::uuid, 'East African Highlands and rift system', FALSE, 3),('f08fc41f-b18d-42b6-841e-911fed424650'::uuid, 'ffa52901-aea0-4d2c-8fed-f853dbcfa85b'::uuid, 'Increase salinity of oceans', TRUE, 0),('c28cbf16-4151-41b0-8d9b-138f746bfefe'::uuid, 'ffa52901-aea0-4d2c-8fed-f853dbcfa85b'::uuid, 'Produce different patterns that determine ecological potential', FALSE, 1),('e588c8da-db80-44d2-8a39-5a935de0a5b6'::uuid, 'ffa52901-aea0-4d2c-8fed-f853dbcfa85b'::uuid, 'Affect the flow of organisms, energy and material', FALSE, 2),('52bc1834-1a2c-49e2-82cb-13187d154e2d'::uuid, 'ffa52901-aea0-4d2c-8fed-f853dbcfa85b'::uuid, 'Affect the spatial pattern of disturbance by fire and wind', FALSE, 3),('0c404c8d-4ecf-48c2-8de9-c755f50d347f'::uuid, 'fbba6f4c-a41c-43a1-85ce-69d43f3216e9'::uuid, 'True', TRUE, 0),('0fb6c700-9372-46c6-8b7a-001e0759f605'::uuid, 'fbba6f4c-a41c-43a1-85ce-69d43f3216e9'::uuid, 'False', FALSE, 1),('7e4e2493-3ec5-4730-8fc9-e6743ca1745c'::uuid, 'c60a6047-c5bf-456b-8593-43d54f7f4950'::uuid, 'True', TRUE, 0),('afae2104-9879-4300-854f-1124f72ddb63'::uuid, 'c60a6047-c5bf-456b-8593-43d54f7f4950'::uuid, 'False', FALSE, 1),('efe76661-ce80-437a-8523-a3dde274ad8a'::uuid, '331b3cf5-f612-4a62-82ea-f388d0c8ad14'::uuid, 'True', FALSE, 0),('3e2f2c36-7816-4931-8370-48ee701b5d82'::uuid, '331b3cf5-f612-4a62-82ea-f388d0c8ad14'::uuid, 'False', TRUE, 1),('b16c0552-2718-4295-8fb3-b56250f7936c'::uuid, '7bf2a8ef-672b-4120-833f-af6075043dab'::uuid, 'True', TRUE, 0),('7bb3ba28-1b97-41b7-8c1e-6ae99a4b1a85'::uuid, '7bf2a8ef-672b-4120-833f-af6075043dab'::uuid, 'False', FALSE, 1) ON CONFLICT (id) DO UPDATE SET question_id = EXCLUDED.question_id, choice_text = EXCLUDED.choice_text, is_correct = EXCLUDED.is_correct, order_index = EXCLUDED.order_index;
INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('f03cdd76-8678-4a8e-840b-c614513e638f'::uuid, 'Geography', 'Unit 2', 'Molarum Grade 10 — Geography Unit 2: Climate of Africa', 'Source-grounded Molarum Grade 10 Geography questions for Unit 2: Climate of Africa.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('7edc3839-7c01-4b3f-8239-75e3b4d0ae7e'::uuid, 'f03cdd76-8678-4a8e-840b-c614513e638f'::uuid, 'multiple_choice', 'According to the excerpt, which statement best defines climate?', 'An average of weather conditions in a place over a long period – 30 years or more.', 'The excerpt defines climate as the average of weather conditions in a place over a long period (30 years or more), distinguishing it from short-term weather conditions.', 0),('75e24b52-b3ae-4f34-8bde-a9d5fb20d06b'::uuid, 'f03cdd76-8678-4a8e-840b-c614513e638f'::uuid, 'multiple_choice', 'Which of the following best describes weather as given in the excerpt?', 'A short-term atmospheric condition such as the temperature and precipitation on a certain day', 'The excerpt states that weather refers to short-term atmospheric conditions like temperature and precipitation on a certain day, distinguishing it from climate.', 1),('3305837a-a523-4b28-82ab-24eb2ad9df8c'::uuid, 'f03cdd76-8678-4a8e-840b-c614513e638f'::uuid, 'multiple_choice', 'In Köppen’s classification mentioned in the excerpt, which group uses precipitation as its primary criterion?', 'B (dry)', 'The excerpt explains that Köppen’s group B (dry) has precipitation as its primary criterion, while the other groups are defined by temperature or altitude.', 2),('ec63cfdf-d066-4b90-83ec-40d3017a52ed'::uuid, 'f03cdd76-8678-4a8e-840b-c614513e638f'::uuid, 'multiple_choice', 'Which Köppen climate designation in the excerpt is determined primarily by altitude?', 'H (highland)', 'The excerpt states that H (highland) in Köppen’s scheme is determined by altitude, distinguishing highland climates from the temperature- or precipitation-defined groups.', 3),('ea18169a-e83a-4121-811d-31f6648480d1'::uuid, 'f03cdd76-8678-4a8e-840b-c614513e638f'::uuid, 'multiple_choice', 'What primary source drives the Earth’s climate according to the excerpt?', 'Energy from the sun which arrives in the form of radiation', 'The excerpt states that the Earth’s climate is driven by energy from the sun which arrives as radiation, making solar radiation the primary driver of climate.', 4),('e7d37d77-a123-48be-81c9-64f7cb2f2177'::uuid, 'f03cdd76-8678-4a8e-840b-c614513e638f'::uuid, 'multiple_choice', 'How did the ancient Greeks divide each hemisphere, as reported in the excerpt?', 'Into three zones: torrid (tropical), temperate, and frigid', 'The excerpt notes that the ancient Greeks divided each hemisphere into three zones—torrid (tropical), temperate, and frigid—as an early climate classification.', 5),('11f1ae1c-63b2-4b1c-86e1-0a127ee282a4'::uuid, 'f03cdd76-8678-4a8e-840b-c614513e638f'::uuid, 'multiple_choice', 'Which climate zone, as defined in the excerpt, lies between 23.5°–40° latitude?', 'Subtropics Zone', 'The excerpt specifies the Subtropics Zone as ranging from 23.5°–40°, distinguishing it from the tropical, temperate, and cold zones.', 6),('831eb283-a4a0-4225-8793-c68a54ad4b19'::uuid, 'f03cdd76-8678-4a8e-840b-c614513e638f'::uuid, 'multiple_choice', 'Which of the following is described in the excerpt as a characteristic of the Tropical Zone (0°–23.5°)?', 'Sunlight reaches the ground nearly vertically and it is very warm with high humidity', 'The excerpt explains that within the tropics the sun’s rays are nearly perpendicular, producing high temperatures, high evaporation, and moist air with frequent cloud cover.', 7),('93ad5176-c1a7-40c7-8872-8b0244c316bc'::uuid, 'f03cdd76-8678-4a8e-840b-c614513e638f'::uuid, 'multiple_choice', 'According to the excerpt, why are most of the world''s deserts situated in the subtropics?', 'Because subtropics receive the highest radiation in summer and relatively less moisture', 'The excerpt states that the subtropics receive high summer radiation and less moisture (e.g., due to trade winds), which contributes to desert formation in this zone.', 8),('316c3e9c-1d76-416e-8fae-992f30a2ea12'::uuid, 'f03cdd76-8678-4a8e-840b-c614513e638f'::uuid, 'multiple_choice', 'Which term from the textbook multiple choice items describes a narrow strip of land with water on both sides connecting two larger pieces of land?', 'Isthmus', 'The earlier multiple choice item in the excerpt defines an isthmus as a narrow strip of land with water on both sides connecting two larger land masses, distinguishing it from peninsula or strait.', 9),('e478575d-8e4e-44ec-866a-937dcb3cdd59'::uuid, 'f03cdd76-8678-4a8e-840b-c614513e638f'::uuid, 'multiple_choice', 'Which of the following is NOT a characteristic of the tropical rainforest in Africa as given in the excerpt?', 'Some species of trees are xerophytic – adapted to dry environment with small leaves and thorns', 'The excerpt lists xerophytic adaptations as not characteristic of tropical rainforests; rainforests are moist and support abundant vegetation, not xerophytic forms.', 10),('d76110e7-d4ea-45b4-8b69-00b8e2a92f1e'::uuid, 'f03cdd76-8678-4a8e-840b-c614513e638f'::uuid, 'multiple_choice', 'Which choice best summarizes the effects of landforms on ecosystem patterns and processes from the excerpt?', 'All', 'The excerpt lists each of these effects, concluding that landforms influence ecological potential, flows of organisms and materials, and disturbance patterns, so ''All'' summarizes the effects.', 11),('23bdca29-3036-48fe-81e5-1e5779a58434'::uuid, 'f03cdd76-8678-4a8e-840b-c614513e638f'::uuid, 'multiple_choice', 'What is the approximate average temperature in the Equatorial climate region as stated in the excerpt?', '26°C', 'The excerpt states that temperatures are very high throughout the equatorial region, averaging about 26°C, with the hottest months when the sun is overhead.', 12),('efe9b7a0-ceeb-499a-8549-7a0e211fcc24'::uuid, 'f03cdd76-8678-4a8e-840b-c614513e638f'::uuid, 'multiple_choice', 'According to the excerpt, what is the typical diurnal temperature range in the equatorial climate region?', 'About 3°C', 'The excerpt states that the diurnal temperature range in the equatorial region is very low, about 3°C, reflecting small day-night variation.', 13),('0e29bccb-21a4-4014-8305-20f6ba17dd61'::uuid, 'f03cdd76-8678-4a8e-840b-c614513e638f'::uuid, 'multiple_choice', 'Which type of rainfall is mainly received in the equatorial climate region, according to the excerpt?', 'Convectional rainfall', 'The excerpt explains that the equatorial region mainly receives convectional rainfall due to intense heating and moisture leading to convectional storms.', 14),('50d8f333-e4bb-41d5-81ef-65aea8433370'::uuid, 'f03cdd76-8678-4a8e-840b-c614513e638f'::uuid, 'multiple_choice', 'What is the great distinguishing feature of the Tropical Wet-and-Dry (savanna) climatic region per the excerpt?', 'Seasonal character of its rainfall with a distinct dry period', 'The excerpt states that the tropical wet-and-dry region is distinguished by a seasonal rainfall pattern, with up to six months of rainfall followed by a dry season.', 15),('c236e037-43ae-4e28-8e8d-878c5cc93470'::uuid, 'f03cdd76-8678-4a8e-840b-c614513e638f'::uuid, 'multiple_choice', 'When does the harmonic wind called the Harmattan typically blow over Sub-Saharan Africa as given in the excerpt?', 'November to April', 'The excerpt notes that the Harmattan, a dry northeasterly or easterly wind, blows over Sub-Saharan Africa from about November to April.', 16),('9bc30651-2f1a-429c-8fb5-af6adad175a9'::uuid, 'f03cdd76-8678-4a8e-840b-c614513e638f'::uuid, 'multiple_choice', 'Which description of the hot desert climatic region is supported by the excerpt?', 'Little or no rainfall with daytime temperatures usually between 30ºC - 40ºC', 'The excerpt describes hot deserts as receiving little or no rainfall and having very high daytime temperatures usually between 30°C and 40°C, with large diurnal ranges.', 17),('ec128c16-2cb3-4509-8c2a-3a06bf461e53'::uuid, 'f03cdd76-8678-4a8e-840b-c614513e638f'::uuid, 'multiple_choice', 'What is the typical annual rainfall amount for the Mediterranean climate region according to the excerpt?', 'About 500–750 mm', 'The excerpt states that the Mediterranean climate region receives about 500–750 mm of rainfall annually due to westerly winds bringing moist air in winter.', 18),('fcba7cd1-4580-4c0c-845c-cfdf97016d05'::uuid, 'f03cdd76-8678-4a8e-840b-c614513e638f'::uuid, 'multiple_choice', 'According to the excerpt, agriculture on the African continent on average accounts for what percentage of the labour force?', 'About 70%', 'The excerpt states that agriculture on average accounts for 70% of the labour force in Africa, underlining the sector''s importance and climate dependence.', 19),('63874bcd-244d-42dc-80a2-8870dd67043e'::uuid, 'f03cdd76-8678-4a8e-840b-c614513e638f'::uuid, 'true_false', 'Climate is defined in the excerpt as an average of weather conditions in a place over a long period (30 years or more).', 'True', 'The excerpt explicitly defines climate as the average of weather conditions over a long period, typically 30 years or more.', 20),('d994ebea-8d64-4b1f-863c-0b826509dfd9'::uuid, 'f03cdd76-8678-4a8e-840b-c614513e638f'::uuid, 'true_false', 'Köppen’s classification uses precipitation as the primary criterion for group B only, and temperature for four groups.', 'True', 'The excerpt states that four of Köppen’s groups are defined by temperature while group B uses precipitation as its primary criterion, making this statement true.', 21),('2991ebd4-d558-462c-8403-80ac56858c52'::uuid, 'f03cdd76-8678-4a8e-840b-c614513e638f'::uuid, 'true_false', 'According to the excerpt, in June the ITCZ is located at about 13 degrees latitude in North Africa at the southern boundary of the Sahara. ', 'True', 'The excerpt explicitly states that in June the ITCZ is located at about 13 degrees latitude in North Africa at the southern boundary of the Sahara, linking ITCZ movement to rainfall distribution.', 22),('faf6ef40-2930-44c2-8f78-7fe5c115dd0a'::uuid, 'f03cdd76-8678-4a8e-840b-c614513e638f'::uuid, 'true_false', 'Cool ocean currents tend to cause winds blowing over them to deposit more moisture on adjacent coasts, increasing rainfall there.', 'False', 'The excerpt explains that cool ocean currents make winds lose moisture (forming fogs) and tend to produce dry conditions on adjacent coasts, so they do not increase rainfall.', 23),('0e9020a0-85c3-4a25-84e9-71b37f6ea6bf'::uuid, 'f03cdd76-8678-4a8e-840b-c614513e638f'::uuid, 'fill_blank', 'Define climate using the exact description given in the excerpt.', 'an average of weather conditions in a place over a long period – 30 years or more.', 'The excerpt defines climate as the average of weather conditions in a place over a long period (30 years or more), distinguishing it from weather.', 24),('bcb5d986-8dd9-46f9-8cd9-8509e22da599'::uuid, 'f03cdd76-8678-4a8e-840b-c614513e638f'::uuid, 'fill_blank', 'Provide the excerpt’s definition of weather.', 'a short-term atmospheric condition such as the temperature and precipitation on a certain day, the state of the atmosphere with respect to heat or cold, wetness or dryness, calm or storm, clearness or cloudiness.', 'The excerpt defines weather as a short-term atmospheric condition exemplified by temperature and precipitation on a certain day and other immediate atmospheric states.', 25),('f8799ed3-9b1e-45fe-8a21-ca7cd9662ec6'::uuid, 'f03cdd76-8678-4a8e-840b-c614513e638f'::uuid, 'fill_blank', 'Which climate classification scheme and author is identified in the excerpt as one of the most widely used?', 'Wladimir Köppen’s classification scheme (Köppen classification).', 'The excerpt identifies German climatologist Wladimir Köppen and his classification scheme as one of the most widely used, based on temperature and precipitation data.', 26),('41abcb23-ee3d-41dc-88d2-45e8196838d6'::uuid, 'f03cdd76-8678-4a8e-840b-c614513e638f'::uuid, 'fill_blank', 'List the four major global climate zones named in the excerpt.', 'Tropical Zone, Subtropics Zone, Temperate Zone, Cold Zone.', 'The excerpt lists four major global climate zones: Tropical (0°–23½°), Subtropics (23½°–40°), Temperate (40°–60°), and Cold (60°–90°).', 27),('66230153-213e-4f02-8dac-ad190e7775cf'::uuid, 'f03cdd76-8678-4a8e-840b-c614513e638f'::uuid, 'fill_blank', 'Name the climatic region that consists of the Sahara and Kalahari deserts as per the excerpt.', 'The Hot Desert Climatic Region.', 'The excerpt states that the hot desert climatic region consists of the Sahara and Kalahari deserts, characterized by little or no rainfall and extreme temperatures.', 28),('0f64b6fa-3574-4725-8576-adb10d1e2d6b'::uuid, 'f03cdd76-8678-4a8e-840b-c614513e638f'::uuid, 'fill_blank', 'State the lapse rate value given in the excerpt.', 'Air temperature decreases with altitude at an average rate of 6.4°C per 1000 meters (lapse rate).', 'The excerpt gives the lapse rate as an average temperature decrease of 6.4°C per 1000 meters, explaining why highlands are cooler.', 29),('ce901afc-8ff4-4d60-89fe-39b285c7a486'::uuid, 'f03cdd76-8678-4a8e-840b-c614513e638f'::uuid, 'fill_blank', 'Give two examples of warm ocean currents affecting Africa as named in the excerpt.', 'Warm Guinea Current and Warm Mozambique Current.', 'The excerpt names the Warm Guinea Current (West Africa) and Warm Mozambique Current (Southeast Africa) as warm currents supplying moisture to adjacent winds.', 30),('1052eb3d-4fda-41f5-866a-72f1ae577b94'::uuid, 'f03cdd76-8678-4a8e-840b-c614513e638f'::uuid, 'fill_blank', 'According to the excerpt, what is the most important factor in determining climate regions of the world?', 'Average temperature is the most important factor in determining climate regions of the world.', 'The excerpt states that average temperature is the most important factor for determining climate regions, though precipitation also plays a role.', 31),('e91b6b2c-7867-4bd7-8ef8-3b14bafb54fe'::uuid, 'f03cdd76-8678-4a8e-840b-c614513e638f'::uuid, 'fill_blank', 'What is the latitudinal width in degrees of the Temperate Zone that ranges from 40°–60° according to the excerpt?', '20°', 'The excerpt defines the Temperate Zone as extending from 40° to 60° latitude; the width is 60° − 40° = 20°.', 32),('9ead7238-9fa5-4163-8bad-bba99fcd4890'::uuid, 'f03cdd76-8678-4a8e-840b-c614513e638f'::uuid, 'fill_blank', 'What is the diurnal (daily) temperature range in the equatorial climate region as stated in the excerpt?', '3°C', 'The excerpt states that the diurnal temperature range in the equatorial region is about 3°C, indicating small day–night temperature variation.', 33),('cb3cdf14-b047-4704-8655-f2bc3c0b1366'::uuid, 'f03cdd76-8678-4a8e-840b-c614513e638f'::uuid, 'fill_blank', 'What is the latitudinal width in degrees of the Tropical Zone stated as 0°–23½° in the excerpt?', '23.5°', 'The excerpt gives the Tropical Zone as from 0° to 23½° latitude; the latitudinal width is 23.5° (23½°).', 34),('7339383b-83e7-440f-82be-b0ab30964c4e'::uuid, 'f03cdd76-8678-4a8e-840b-c614513e638f'::uuid, 'fill_blank', 'Calculate the latitudinal width in degrees of the Subtropics Zone given as 23.5°–40° in the excerpt.', '16.5°', 'The Subtropics Zone is given as 23.5° to 40° latitude, so the width is 40° − 23.5° = 16.5°.', 35),('233d45b1-ef96-456d-83b1-b8ba095412cd'::uuid, 'f03cdd76-8678-4a8e-840b-c614513e638f'::uuid, 'fill_blank', 'What is the approximate temperature difference between winter (10°C) and summer (about 21°C) in the Mediterranean climate region as given in the excerpt?', '11°C', 'The excerpt gives winter temperatures around 10°C and summer about 21°C in the Mediterranean region, so the difference is 21°C − 10°C = 11°C.', 36),('015ab981-8aed-49a1-8a09-d26b14b32f4a'::uuid, 'f03cdd76-8678-4a8e-840b-c614513e638f'::uuid, 'fill_blank', 'What is the difference between the maximum and minimum annual rainfall amounts (in mm) for the Warm Temperate East Coast Climate Region given as 1000–1500 mm in the excerpt?', '500 mm', 'The excerpt gives annual rainfall for the Warm Temperate East Coast as 1000–1500 mm; the difference between maximum and minimum is 1500 − 1000 = 500 mm.', 37),('384964af-b972-4691-8c59-5bf8efd2017a'::uuid, 'f03cdd76-8678-4a8e-840b-c614513e638f'::uuid, 'fill_blank', 'According to the excerpt, the Warm Temperate Continental Climate Region has annual temperatures ranging from about 26°C in summer to about 10°C in winter; what is the annual temperature range in °C?', '16°C', 'The excerpt reports summer temperatures of about 26°C and winter about 10°C for this region, so the annual range is 26°C − 10°C = 16°C.', 38),('952497f9-299f-44d1-8e1b-c5cced311acb'::uuid, 'f03cdd76-8678-4a8e-840b-c614513e638f'::uuid, 'fill_blank', 'Using values given in the excerpt, how many degrees Celsius warmer is the highest ever recorded temperature (58°C in Azizia) than the Mediterranean summer temperature of about 21°C?', '37°C', 'The excerpt gives the highest recorded temperature as 58°C and Mediterranean summer about 21°C; the difference is 58°C − 21°C = 37°C.', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
