uuid, 'e478575d-8e4e-44ec-866a-937dcb3cdd59'::uuid, 'Different plants exhibit different stages of growth at the same time due to absence of climatic season', FALSE, 1),('5171161d-043d-4aa5-8626-37db8024f588'::uuid, 'e478575d-8e4e-44ec-866a-937dcb3cdd59'::uuid, 'Some species of trees are xerophytic – adapted to dry environment with small leaves and thorns', TRUE, 2),('b3fd907a-debb-4fed-89d6-4c367c4dfeac'::uuid, 'e478575d-8e4e-44ec-866a-937dcb3cdd59'::uuid, 'Trees have little undergrowth as canopies prevent light penetration', FALSE, 3),('0b3ca67d-ca7e-4bde-8a2c-c029337eda2f'::uuid, 'd76110e7-d4ea-45b4-8b69-00b8e2a92f1e'::uuid, 'Landform attributes produce different patterns determining ecological potential', FALSE, 0),('64f78313-c87c-4e70-8286-edeeaf8fb79f'::uuid, 'd76110e7-d4ea-45b4-8b69-00b8e2a92f1e'::uuid, 'Landform regions affect the flow of organisms, energy and material', FALSE, 1),('b612c6ee-0f79-441f-8695-0a715b873989'::uuid, 'd76110e7-d4ea-45b4-8b69-00b8e2a92f1e'::uuid, 'Landform regions affect spatial pattern of non-geomorphic disturbance by fire and wind', FALSE, 2),('40ff8fe9-566b-4891-8781-4fcaac7dbe3b'::uuid, 'd76110e7-d4ea-45b4-8b69-00b8e2a92f1e'::uuid, 'All', TRUE, 3),('9f0db0a4-26ba-4ad0-8819-778f646b51df'::uuid, '23bdca29-3036-48fe-81e5-1e5779a58434'::uuid, '10°C', FALSE, 0),('781caf0b-1b95-47b2-8a4f-bdf10dc33973'::uuid, '23bdca29-3036-48fe-81e5-1e5779a58434'::uuid, '21°C', FALSE, 1),('253daf8c-64a1-475c-8c0d-fa128d1cacd6'::uuid, '23bdca29-3036-48fe-81e5-1e5779a58434'::uuid, '26°C', TRUE, 2),('89cefe66-0e23-4016-8832-281936dbdc2f'::uuid, '23bdca29-3036-48fe-81e5-1e5779a58434'::uuid, '30°C', FALSE, 3),('393999a8-3f77-40df-8256-23277b54f5d6'::uuid, 'efe9b7a0-ceeb-499a-8549-7a0e211fcc24'::uuid, 'About 3°C', TRUE, 0),('96197568-b6a3-4e1a-83d6-82413043cd83'::uuid, 'efe9b7a0-ceeb-499a-8549-7a0e211fcc24'::uuid, 'About 10°C', FALSE, 1),('8a867d70-998c-4b5c-869e-2c8d631a1f4d'::uuid, 'efe9b7a0-ceeb-499a-8549-7a0e211fcc24'::uuid, 'About 15°C', FALSE, 2),('0ad94b68-884e-4d72-810f-c16121534ad5'::uuid, 'efe9b7a0-ceeb-499a-8549-7a0e211fcc24'::uuid, 'About 0.5°C', FALSE, 3),('94cf7ade-a49a-4d5a-81f0-b127fc263cf8'::uuid, '0e29bccb-21a4-4014-8305-20f6ba17dd61'::uuid, 'Orographic rainfall', FALSE, 0),('ca1e5340-be67-4e17-8ca8-2ecf78ec376a'::uuid, '0e29bccb-21a4-4014-8305-20f6ba17dd61'::uuid, 'Frontal rainfall', FALSE, 1),('af5ff790-d850-4cdb-8013-051ecb585acf'::uuid, '0e29bccb-21a4-4014-8305-20f6ba17dd61'::uuid, 'Convectional rainfall', TRUE, 2),('d6c97a82-be57-4ff7-86fa-7ac014cc71b2'::uuid, '0e29bccb-21a4-4014-8305-20f6ba17dd61'::uuid, 'Cyclonic rainfall', FALSE, 3),('58494036-6f3c-47e9-84b8-ca402cd250a3'::uuid, '50d8f333-e4bb-41d5-81ef-65aea8433370'::uuid, 'Uniform rainfall all year round', FALSE, 0),('919f4891-c67a-4260-8dd4-aa46813d27c2'::uuid, '50d8f333-e4bb-41d5-81ef-65aea8433370'::uuid, 'Seasonal character of its rainfall with a distinct dry period', TRUE, 1),('363dc25d-c300-41d8-84ce-fff089a5e2c0'::uuid, '50d8f333-e4bb-41d5-81ef-65aea8433370'::uuid, 'Perennial river systems providing constant moisture', FALSE, 2),('ad3772b2-ad5a-4d64-84de-5f606ed294b3'::uuid, '50d8f333-e4bb-41d5-81ef-65aea8433370'::uuid, 'High snowfall in winter months', FALSE, 3),('965fc0ab-f077-40b5-8cab-9b18c5af4d6d'::uuid, 'c236e037-43ae-4e28-8e8d-878c5cc93470'::uuid, 'May to September', FALSE, 0),('2deafb66-8478-4891-89b5-31037653fa25'::uuid, 'c236e037-43ae-4e28-8e8d-878c5cc93470'::uuid, 'November to April', TRUE, 1),('cc9b6487-ceb7-4b51-8fba-1e026c2c7e29'::uuid, 'c236e037-43ae-4e28-8e8d-878c5cc93470'::uuid, 'June to August', FALSE, 2),('05aecf37-2557-42c2-85ff-64dc5b1f8b4b'::uuid, 'c236e037-43ae-4e28-8e8d-878c5cc93470'::uuid, 'September to November', FALSE, 3),('7c3edc94-8244-49b0-853c-d5cfe86370e4'::uuid, '9bc30651-2f1a-429c-8fb5-af6adad175a9'::uuid, 'Frequent and heavy convectional rainfall', FALSE, 0),('fd8b906e-8f22-475d-88af-4c4202e0d69a'::uuid, '9bc30651-2f1a-429c-8fb5-af6adad175a9'::uuid, 'Little or no rainfall with daytime temperatures usually between 30ºC - 40ºC', TRUE, 1),('38f965f8-d672-4f1c-8a59-efa4a839932f'::uuid, '9bc30651-2f1a-429c-8fb5-af6adad175a9'::uuid, 'Low daytime temperatures with high night humidity', FALSE, 2),('1762f392-4d8e-42f8-81b9-0830c2daa506'::uuid, '9bc30651-2f1a-429c-8fb5-af6adad175a9'::uuid, 'Rainfall evenly distributed through the year', FALSE, 3),('bbc5f1cb-d505-4cfb-830f-51f9b205e495'::uuid, 'ec128c16-2cb3-4509-8c2a-3a06bf461e53'::uuid, 'Less than 200 mm', FALSE, 0),('5c4ec3b1-9e58-41e4-8229-11bb74d4387c'::uuid, 'ec128c16-2cb3-4509-8c2a-3a06bf461e53'::uuid, 'About 500–750 mm', TRUE, 1),('6d7dc183-b37f-4f7e-8773-9d367f678939'::uuid, 'ec128c16-2cb3-4509-8c2a-3a06bf461e53'::uuid, '1000–1500 mm', FALSE, 2),('809739b1-7b2c-4ed1-88bb-d8f814f1429f'::uuid, 'ec128c16-2cb3-4509-8c2a-3a06bf461e53'::uuid, 'Over 2000 mm', FALSE, 3),('78a25ad4-6a6c-4121-8f46-53d0648abd51'::uuid, 'fcba7cd1-4580-4c0c-845c-cfdf97016d05'::uuid, 'About 25%', FALSE, 0),('f0231f86-03cc-4bde-8d4c-d1262a000531'::uuid, 'fcba7cd1-4580-4c0c-845c-cfdf97016d05'::uuid, 'About 70%', TRUE, 1),('16d6bc88-e9dc-4c56-87fc-5590b6528706'::uuid, 'fcba7cd1-4580-4c0c-845c-cfdf97016d05'::uuid, 'About 40%', FALSE, 2),('cb437c24-ad72-4781-84d3-f1e268b2fdb9'::uuid, 'fcba7cd1-4580-4c0c-845c-cfdf97016d05'::uuid, 'About 10%', FALSE, 3),('c0d17dc6-3888-4ab9-83e8-7224f43f6e3a'::uuid, '63874bcd-244d-42dc-80a2-8870dd67043e'::uuid, 'True', TRUE, 0),('8b42e770-6413-41ac-8d3f-ea43c2366ecc'::uuid, '63874bcd-244d-42dc-80a2-8870dd67043e'::uuid, 'False', FALSE, 1),('ca40239f-689f-4887-831b-4b79093b9418'::uuid, 'd994ebea-8d64-4b1f-863c-0b826509dfd9'::uuid, 'True', TRUE, 0),('16d970e2-6bb1-4fa1-831d-85be3e6d68e2'::uuid, 'd994ebea-8d64-4b1f-863c-0b826509dfd9'::uuid, 'False', FALSE, 1),('82acdc49-e4b1-4192-8446-89304ab56302'::uuid, '2991ebd4-d558-462c-8403-80ac56858c52'::uuid, 'True', TRUE, 0),('0acdcbd2-eaff-4af2-8aef-b9e875b5caaf'::uuid, '2991ebd4-d558-462c-8403-80ac56858c52'::uuid, 'False', FALSE, 1),('9b1c2e64-a79c-45ce-89f1-4daee6ce7822'::uuid, 'faf6ef40-2930-44c2-8f78-7fe5c115dd0a'::uuid, 'True', FALSE, 0),('a41abe26-9669-49f4-8ff6-2f8d79a5d1b1'::uuid, 'faf6ef40-2930-44c2-8f78-7fe5c115dd0a'::uuid, 'False', TRUE, 1) ON CONFLICT (id) DO UPDATE SET question_id = EXCLUDED.question_id, choice_text = EXCLUDED.choice_text, is_correct = EXCLUDED.is_correct, order_index = EXCLUDED.order_index;
INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('e7267dc0-c634-44ae-866f-c87d700611aa'::uuid, 'Geography', 'Unit 3', 'Molarum Grade 10 — Geography Unit 3: Natural Resource Base of Africa', 'Source-grounded Molarum Grade 10 Geography questions for Unit 3: Natural Resource Base of Africa.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('b9288ec8-aacc-49e2-855d-e8949ef4aea8'::uuid, 'e7267dc0-c634-44ae-866f-c87d700611aa'::uuid, 'multiple_choice', 'Which of the following is identified in the text as a renewable resource?', 'Sunlight', 'The text states that renewable resources include examples such as sunlight and wind, while petroleum and coal are nonrenewable.', 0),('3e2307b3-aeba-43c3-8869-75b63438da72'::uuid, 'e7267dc0-c634-44ae-866f-c87d700611aa'::uuid, 'multiple_choice', 'According to the text, approximately what percentage of all Earth’s water is freshwater?', '2.5%', 'The text specifies that only about 2.5% of the total amount of water on Earth is freshwater.', 1),('2a7fe8e7-cbb9-417e-8ef8-710ee6945ab5'::uuid, 'e7267dc0-c634-44ae-866f-c87d700611aa'::uuid, 'multiple_choice', 'Which statement best describes sustainable use as defined in the text?', 'Using resources at a rate that does not lead to long-term environmental degradation', 'Sustainable use is described as using resources in a way and at a rate that does not cause long-term degradation, maintaining potential for present and future generations.', 2),('cf603e3c-c1a8-4b85-8f49-b1d67aac8385'::uuid, 'e7267dc0-c634-44ae-866f-c87d700611aa'::uuid, 'multiple_choice', 'Which is listed as a key strategy for sustainable natural resource management?', 'Conserving and recovering biodiversity', 'The focus box lists conserving and recovering biodiversity as one of the key strategies of sustainable natural resource management.', 3),('ef166671-de9b-4336-890a-0f115a448bb5'::uuid, 'e7267dc0-c634-44ae-866f-c87d700611aa'::uuid, 'multiple_choice', 'Which statement about oil is explicitly stated in the text?', 'Nearly all transportation and manufacturing industries rely on petroleum products', 'The text states that nearly all transportation and manufacturing industries rely on petroleum products, and emphasizes oil’s scarcity and nonrenewable nature.', 4),('b4520476-862c-4162-8930-2387ebe47c69'::uuid, 'e7267dc0-c634-44ae-866f-c87d700611aa'::uuid, 'multiple_choice', 'Which river is described as about 6,650 kilometers long and the longest river in the world?', 'The Nile', 'The text identifies the Nile as about 6,650 km long and the longest river in the world.', 5),('1cfe052a-1b5b-4417-866b-b99387ae660d'::uuid, 'e7267dc0-c634-44ae-866f-c87d700611aa'::uuid, 'multiple_choice', 'Approximately what percentage of Nile water is stated to come from Ethiopia?', '86%', 'The text states that 86% of the Nile’s water comes from Ethiopia via its right-bank tributaries.', 6),('86d1f56f-c4bb-4b71-8e3a-0101cbb4e716'::uuid, 'e7267dc0-c634-44ae-866f-c87d700611aa'::uuid, 'multiple_choice', 'What is the Congo River’s estimated hydroelectric potential according to the text?', '100,000 MW', 'The text estimates the Congo River’s hydroelectric potential at 100,000 MW, with 44,000 MW potentially from the Inga site alone.', 7),('8e46d2c3-11e6-43e3-8212-96f03013cb1b'::uuid, 'e7267dc0-c634-44ae-866f-c87d700611aa'::uuid, 'multiple_choice', 'Which famous waterfall is located on the Zambezi River?', 'Victoria Falls', 'The text notes that the Zambezi River has numerous waterfalls, the most spectacular being the Victoria Falls.', 8),('884958ea-15aa-45a2-84a5-ce1ff7d94255'::uuid, 'e7267dc0-c634-44ae-866f-c87d700611aa'::uuid, 'multiple_choice', 'What is the mean depth of Lake Chad as stated in the text?', '1.2 meters', 'Lake Chad is described as a shallow lake with a mean depth of 1.2 meters.', 9),('5e90cc07-8fba-4710-8897-1dc7777fec0b'::uuid, 'e7267dc0-c634-44ae-866f-c87d700611aa'::uuid, 'multiple_choice', 'Which soil type is identified as the dominant soil in Africa by area?', 'Arenosols', 'Arenosols are described as the dominant soil in Africa, covering about 22% of the continent’s soils.', 10),('79fe15a5-f83d-43e2-8f0c-f213f8ae62c6'::uuid, 'e7267dc0-c634-44ae-866f-c87d700611aa'::uuid, 'multiple_choice', 'Which description matches Leptosols as defined in the text?', 'Shallow soil over hard rock or very gravelly material', 'Leptosols are defined as shallow soils over hard rock, very gravelly material, or highly calcareous deposits.', 11),('68a732f7-afa5-4320-8fae-7018cafb2f0c'::uuid, 'e7267dc0-c634-44ae-866f-c87d700611aa'::uuid, 'multiple_choice', 'Which soil type may form a solid hard pan (calcrete) impenetrable to plant roots?', 'Calcisols', 'The text states that precipitated calcium carbonate in Calcisols can cement soil pores and form a hard pan (calcrete) impenetrable to roots.', 12),('f5f30f30-255c-4c6d-8c9f-84ea0c9e93c6'::uuid, 'e7267dc0-c634-44ae-866f-c87d700611aa'::uuid, 'multiple_choice', 'Which country is identified in the text as producing more than half of the world’s cobalt?', 'Democratic Republic of Congo', 'The mineral-resources text states that the Democratic Republic of Congo produces more than half of the world’s cobalt.', 13),('3eec07c5-cb96-43c9-8bb6-4d3154cde63d'::uuid, 'e7267dc0-c634-44ae-866f-c87d700611aa'::uuid, 'multiple_choice', 'Which transportation investment focus during colonial times is highlighted in the text?', 'Railroads were built to carry minerals to coastal ports', 'The text notes colonial powers built railroads to carry minerals to ports, not to link cities or other industries.', 14),('a3dbb97c-2fe5-45bb-88ef-b1a588f83bfc'::uuid, 'e7267dc0-c634-44ae-866f-c87d700611aa'::uuid, 'multiple_choice', 'Which description of Africa’s tropical rainforests is stated in the text?', 'They occur in central Africa on both sides of the Equator and on the eastern coast of Madagascar', 'The vegetation section locates tropical rainforests in central Africa, on both sides of the Equator, and on the eastern coast of Madagascar.', 15),('0f5274f0-566f-4943-8d9f-d79c2c43fd15'::uuid, 'e7267dc0-c634-44ae-866f-c87d700611aa'::uuid, 'multiple_choice', 'Where is the most extensive formation of tropical rainforest in Africa located?', 'Guineo-Congolian lowland concentrated in the Congo Basin', 'The text identifies the most extensive rainforests in the Guineo-Congolian lowland, concentrated in the Congo Basin.', 16),('bb23de25-e1cb-44ca-84bd-1ababbb5f966'::uuid, 'e7267dc0-c634-44ae-866f-c87d700611aa'::uuid, 'multiple_choice', 'According to the text, which factors explain why Somalia is dry despite lying across the Equator?', 'Trade winds blow parallel to the coast and the winter Indian monsoon reaches after crossing large continents', 'The text explains Somalia’s dryness by trade winds parallel to the coast bringing little humidity and the winter Indian monsoon arriving after crossing large continents.', 17),('9e8ecfe3-cc98-4be3-8c72-e1c88ea4e104'::uuid, 'e7267dc0-c634-44ae-866f-c87d700611aa'::uuid, 'multiple_choice', 'Where are subtropical dry forests found in Africa, and when does most rainfall occur there?', 'In Mediterranean climates of North and South Africa; most rainfall occurs in winter', 'The subtropical dry forests are confined to Mediterranean climates of North and South Africa, with most rainfall in winter (400–1000 mm/year).', 18),('2ceab116-cc03-43a3-87e8-cccd157cd4c5'::uuid, 'e7267dc0-c634-44ae-866f-c87d700611aa'::uuid, 'multiple_choice', 'Which animal is identified in the text as unique to Africa?', 'Aardvark', 'The text specifically states that the aardvark is an animal unique to Africa.', 19),('cda40411-4282-4d90-81c6-70a72a8025d1'::uuid, 'e7267dc0-c634-44ae-866f-c87d700611aa'::uuid, 'true_false', 'Sustainable use of resources means using them at a rate that does not cause long-term environmental degradation and preserves their potential for present and future generations.', 'True', 'The text defines sustainable use as using resources in a way and at a rate that avoids long-term environmental degradation and maintains their potential for current and future generations.', 20),('8e22f137-6e03-48f7-875a-6712d9c53b77'::uuid, 'e7267dc0-c634-44ae-866f-c87d700611aa'::uuid, 'true_false', 'The Congo River is Africa’s second-longest river and is accessible in all seasons because parts of its basin lie on both sides of the Equator, stabilizing its flow.', 'True', 'The text states the Congo is Africa’s second-longest river and, with basin areas both above and below the Equator, its flow is stable so the river is accessible in all seasons.', 21),('644a6cfa-65f4-4f7c-8672-a5baf0c8c184'::uuid, 'e7267dc0-c634-44ae-866f-c87d700611aa'::uuid, 'true_false', 'Arenosols are the dominant soil type in Africa, covering about 22% of the continent’s soils.', 'True', 'The soils section identifies Arenosols as the dominant soil in Africa and notes they cover 22% of African soils.', 22),('e28d70f3-b87b-43a4-8102-74031940907b'::uuid, 'e7267dc0-c634-44ae-866f-c87d700611aa'::uuid, 'true_false', 'Africa has more diverse wildlife than any other continent.', 'True', 'The wildlife section explicitly states that Africa has more diverse wildlife than any other continent.', 23),('0761ccaa-c037-41a7-8292-8ecda084c897'::uuid, 'e7267dc0-c634-44ae-866f-c87d700611aa'::uuid, 'fill_blank', 'Into what two categories are natural resources classified in this unit?', 'Renewable and nonrenewable resources', 'The text states that natural resources are categorized into renewable resources and nonrenewable resources.', 24),('dc872769-8aa8-4c30-8abb-55fd632727ca'::uuid, 'e7267dc0-c634-44ae-866f-c87d700611aa'::uuid, 'fill_blank', 'What term is defined as the use of resources in a way and at a rate that does not cause long-term environmental degradation?', 'Sustainable use', 'Sustainable use is defined as using resources without leading to long-term environmental degradation, preserving them for present and future generations.', 25),('7c848cef-8929-4862-8465-3a2b3c44ba79'::uuid, 'e7267dc0-c634-44ae-866f-c87d700611aa'::uuid, 'fill_blank', 'What percentage of all the water on Earth is freshwater?', '2.5%', 'The text states that only about 2.5% of Earth’s total water is freshwater.', 26),('8f747f07-ef18-4008-8ca2-a96de7f61566'::uuid, 'e7267dc0-c634-44ae-866f-c87d700611aa'::uuid, 'fill_blank', 'What term refers to the sustainable utilization of land, water, air, minerals, forests, fisheries, and wild flora and fauna?', 'Natural Resource Management (NRM)', 'The unit defines Natural Resource Management (NRM) as the sustainable utilization of these major natural resources.', 27),('24cc005e-daa0-4468-8f96-1a57abd341f8'::uuid, 'e7267dc0-c634-44ae-866f-c87d700611aa'::uuid, 'fill_blank', 'Approximately how long is the Nile River?', 'About 6,650 km', 'The Nile is stated to be about 6,650 kilometers long, making it the longest river in the world.', 28),('8c3fdfc2-00e6-45f9-85b6-9b4ff85e97e9'::uuid, 'e7267dc0-c634-44ae-866f-c87d700611aa'::uuid, 'fill_blank', 'What percentage of the Nile’s water comes from Ethiopia?', '86%', 'The text specifies that 86% of Nile water comes from Ethiopia via its right-bank tributaries.', 29),('272740f2-f080-41ba-8f8a-6d1a8297042e'::uuid, 'e7267dc0-c634-44ae-866f-c87d700611aa'::uuid, 'fill_blank', 'Which African river has an estimated hydroelectric potential of about 100,000 MW, including roughly 44,000 MW at the Inga site?', 'The Congo River', 'The Congo River’s hydroelectric potential is estimated at 100,000 MW, with about 44,000 MW at Inga Falls in the DRC.', 30),('e631c27b-612d-4de5-8ede-27202e75ddb8'::uuid, 'e7267dc0-c634-44ae-866f-c87d700611aa'::uuid, 'fill_blank', 'Which soil group is the most extensive in Africa by area?', 'Arenosols', 'Arenosols are identified as the dominant soil in Africa, covering about 22% of the continent’s soils.', 31),('625188a9-44f1-4157-8c70-dfbd3d84745d'::uuid, 'e7267dc0-c634-44ae-866f-c87d700611aa'::uuid, 'fill_blank', 'If about 71% of Earth’s surface is covered by water, what percentage is land?', '29%', 'Total surface = 100%. Land = 100% − 71% = 29%. Unit: percent of Earth’s surface.', 32),('dee2547e-62a3-485a-86c5-cdfc3a12dd23'::uuid, 'e7267dc0-c634-44ae-866f-c87d700611aa'::uuid, 'fill_blank', 'Freshwater makes up about 2.5% of Earth’s total water. What percentage is not freshwater?', '97.5%', 'Non-freshwater = 100% − 2.5% = 97.5%. Unit: percent of Earth’s total water.', 33),('f1596570-d370-4e8f-8e9e-25034fe75087'::uuid, 'e7267dc0-c634-44ae-866f-c87d700611aa'::uuid, 'fill_blank', 'Ethiopia contributes 86% of the Nile’s water. What percentage comes from other sources?', '14%', 'Other sources = 100% − 86% = 14%. Unit: percent of Nile water.', 34),('34126c9d-a4bc-4614-8481-fb911cc982ab'::uuid, 'e7267dc0-c634-44ae-866f-c87d700611aa'::uuid, 'fill_blank', 'The Congo River’s hydroelectric potential is about 100,000 MW, of which 44,000 MW may come from the Inga site. What percent of the total is at Inga?', '44%', 'Percentage at Inga = (44,000 ÷ 100,000) × 100 = 44%. Unit: percent of total hydroelectric potential.', 35),('135918f0-0f69-4ea7-8f12-bd329dfb8b4a'::uuid, 'e7267dc0-c634-44ae-866f-c87d700611aa'::uuid, 'fill_blank', 'The Zambezi River is about 3,540 km long, and about 2,600 km is navigable by small boats. Approximately what percent of its length is navigable by small boats?', 'Approximately 73.45%', 'Percent navigable ≈ (2,600 km ÷ 3,540 km) × 100 ≈ 0.734463×100 ≈ 73.45%. Unit: percent of total river length.', 36),('681bb0e5-7c0c-4974-82ff-492df4cbef11'::uuid, 'e7267dc0-c634-44ae-866f-c87d700611aa'::uuid, 'fill_blank', 'Lake Chad’s surface area varies seasonally from about 10,360 km² to about 25,900 km². By how many square kilometers does it increase from minimum to maximum?', '15,540 km²', 'Increase = 25,900 km² − 10,360 km² = 15,540 km². Unit: square kilometers (km²).', 37),('c1e2c982-1468-4549-8ad5-0fc555cb26c0'::uuid, 'e7267dc0-c634-44ae-866f-c87d700611aa'::uuid, 'fill_blank', 'The Congo Basin drains about 3.7 million km², while the Zambezi Basin occupies approximately 1,199,164 km². What is the difference in their basin areas?', '2,500,836 km²', 'Convert 3.7 million km² to 3,700,000 km². Difference = 3,700,000 km² − 1,199,164 km² = 2,500,836 km². Unit: square kilometers (km²).', 38),('f445daac-8db8-4a80-8434-e1abd707bbb5'::uuid, 'e7267dc0-c634-44ae-866f-c87d700611aa'::uuid, 'fill_blank', 'Arenosols cover 22% of Africa’s soils, Leptosols 17%, Cambisols 11%, Ferralsols 10%, and Calcisols 6%. What percentage of Africa’s soils do these five groups cover combined?', '66%', 'Combined coverage = 22% + 17% + 11% + 10% + 6% = 66%. Unit: percent of Africa’s soils.', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
