INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('2692abc8-37a0-45f0-8cdb-63203f9400cd'::uuid, '9efc0547-9308-4f01-80b3-7a0a6da7b545'::uuid, 'multiple_choice', 'Which continent is characterized by the highest percentage of the young population according to the excerpt?', 'Africa', 'The excerpt states Africa has a generally young population and high fertility and mortality rates, indicating the highest percentage of young people.', 0),('28e41ac4-cb90-4dd2-8cc8-0b4ea487eca1'::uuid, '9efc0547-9308-4f01-80b3-7a0a6da7b545'::uuid, 'multiple_choice', 'Which type of population pyramid indicates the prevalence of high fertility and mortality rates as given in the excerpt?', 'Triangular population pyramid', 'The excerpt specifically mentions a triangular population pyramid as indicating high fertility and mortality rates in Africa.', 1),('29c194e4-ae3a-4295-80c5-026832d63639'::uuid, '9efc0547-9308-4f01-80b3-7a0a6da7b545'::uuid, 'multiple_choice', 'What was the continent’s average crude population density during mid-2019 as stated in the excerpt?', '44 people/km2', 'The excerpt reports the continent’s average crude population density during mid-2019 was about 44 people/km2.', 2),('3d3134ef-223f-4f93-8163-441668571110'::uuid, '9efc0547-9308-4f01-80b3-7a0a6da7b545'::uuid, 'multiple_choice', 'Which major region of Africa is reported in the excerpt as having a crude population density of 65 persons/km2?', 'Eastern Africa', 'Table 4.9 in the excerpt shows Eastern Africa (along with Western Africa) has a crude density of 65 persons/km2.', 3),('d3fcefbc-61f5-4e63-894d-2a3a461e028f'::uuid, '9efc0547-9308-4f01-80b3-7a0a6da7b545'::uuid, 'multiple_choice', 'Which region is indicated in the excerpt as having the continent’s lowest crude density in 2019?', 'Southern Africa', 'The excerpt states Southern Africa has the continent’s lowest crude density of 25 persons/km2 in 2019.', 4),('44cefd68-cbce-497a-80bf-7a7ea92af7c7'::uuid, '9efc0547-9308-4f01-80b3-7a0a6da7b545'::uuid, 'multiple_choice', 'Which of the following countries is listed in the excerpt among Africa’s most densely populated countries?', 'Mauritius', 'The excerpt lists Mauritius (along with Rwanda, Burundi, Comoros, and Seychelles) as one of the most densely populated countries in Africa.', 5),('ae04af51-cc08-4f30-8714-09830eff092b'::uuid, '9efc0547-9308-4f01-80b3-7a0a6da7b545'::uuid, 'multiple_choice', 'Which activity best describes the primary sector as defined in the excerpt?', 'Extracting raw materials', 'The excerpt defines the primary sector as involving extracting raw materials, rearing animals, and growing crops.', 6),('79aef412-959a-4c14-803e-8b7295164946'::uuid, '9efc0547-9308-4f01-80b3-7a0a6da7b545'::uuid, 'multiple_choice', 'Which description corresponds to the secondary sector according to the excerpt?', 'Changing of raw materials into new products (finished products)', 'The excerpt explains the secondary sector involves changing raw materials into finished products, i.e., manufacturing.', 7),('72f96f32-c9a9-4376-898d-5884332a6394'::uuid, '9efc0547-9308-4f01-80b3-7a0a6da7b545'::uuid, 'multiple_choice', 'Which of the following cannot be included under tertiary activity as illustrated in the excerpt?', 'Tannery', 'The excerpt describes the tertiary sector as services (transport, education, entertainment), whereas tannery is a manufacturing activity of the secondary sector.', 8),('3a766c28-5de0-4326-8445-ad6ee7ce0d8f'::uuid, '9efc0547-9308-4f01-80b3-7a0a6da7b545'::uuid, 'multiple_choice', 'Which of the following is listed in the excerpt as a major factor hindering the growth of Africa’s economy?', 'All of the above', 'The excerpt lists limitations in technology, over-dependence on foreign aid, and poor education among the factors hindering Africa’s economic growth.', 9),('b943dc13-303d-4fe9-81e2-501bc0ef406a'::uuid, '9efc0547-9308-4f01-80b3-7a0a6da7b545'::uuid, 'multiple_choice', 'About what fraction of the continent’s working population is employed in agriculture according to the excerpt?', 'Two-thirds', 'The excerpt states agriculture provides employment for about two-thirds of the continent’s working population.', 10),('f82bf023-c85b-47c9-8deb-235bcd68546f'::uuid, '9efc0547-9308-4f01-80b3-7a0a6da7b545'::uuid, 'multiple_choice', 'What range does the excerpt give for agriculture’s contribution to GDP in many African countries?', '30 to 60 percent of GDP', 'The excerpt reports agriculture contributes on average 30 to 60 percent of GDP in African countries.', 11),('4cb0e9e9-d9ec-41ff-8713-75cbb6ce9124'::uuid, '9efc0547-9308-4f01-80b3-7a0a6da7b545'::uuid, 'multiple_choice', 'According to the excerpt, Africa’s 624 million hectares of forests comprise what percentage of the continent’s land area?', '20.6 percent', 'The excerpt specifies Africa has 624 million hectares under forests, comprising 20.6 percent of the continent’s land area.', 12),('57d86aec-487b-4ed0-840c-02414648048d'::uuid, '9efc0547-9308-4f01-80b3-7a0a6da7b545'::uuid, 'multiple_choice', 'Which role of fisheries is mentioned in the excerpt?', 'They contribute to food and nutrition security', 'The excerpt states fisheries play significant economic and nutritional roles, contributing to food and nutrition security and providing jobs.', 13),('e369f6a9-d940-44b4-823f-4b06bac4d0a4'::uuid, '9efc0547-9308-4f01-80b3-7a0a6da7b545'::uuid, 'multiple_choice', 'Which of the following is NOT listed among Agenda 2063 flagship programs in the excerpt?', 'Eradicating poverty in all its forms and dimensions by 2030', 'Eradicating poverty by 2030 is an SDG (Goal 1) mentioned under SDGs, not listed among Agenda 2063 flagship programs in the excerpt.', 14),('4d8d2f24-84a0-4316-8f40-dcda43e26cb0'::uuid, '9efc0547-9308-4f01-80b3-7a0a6da7b545'::uuid, 'multiple_choice', 'Over how many years is Agenda 2063 intended to be implemented according to the excerpt?', '50 years', 'The excerpt explains Agenda 2063 is a 50-year strategic framework running from 2013 to 2063.', 15),('95706ba9-51ea-43a2-83ac-f6a9573ea7f7'::uuid, '9efc0547-9308-4f01-80b3-7a0a6da7b545'::uuid, 'multiple_choice', 'Which of the following is one of the main aims of Agenda 2063 as stated in the excerpt?', 'Inclusive social and economic development', 'The excerpt lists inclusive social and economic development among the main aims of Agenda 2063, along with continental integration, governance, and peace.', 16),('f80eebbb-c112-438e-8abc-a4fc70184591'::uuid, '9efc0547-9308-4f01-80b3-7a0a6da7b545'::uuid, 'multiple_choice', 'In what year were the Sustainable Development Goals (SDGs) set up according to the excerpt?', '2015', 'The excerpt states the SDGs were set up in 2015 by the United Nations General Assembly.', 17),('da056cf8-43b8-4f4e-8350-f3d78ebaf407'::uuid, '9efc0547-9308-4f01-80b3-7a0a6da7b545'::uuid, 'multiple_choice', 'By which target year are the SDGs intended to be achieved as indicated in the excerpt?', '2030', 'The excerpt states the SDGs were intended to be achieved by the year 2030 as part of Agenda 2030.', 18),('102b00e9-e225-42cc-8c17-460e56b40413'::uuid, '9efc0547-9308-4f01-80b3-7a0a6da7b545'::uuid, 'multiple_choice', 'According to the excerpt, the threshold for absolute poverty used in SDG Goal 1 is what daily income level?', 'US$1.90 a day', 'The excerpt explains that absolute poverty is defined as earning less than US$1.90 a day in the SDG context.', 19),('cc52e267-e73e-4c81-8aed-5808dfa199b0'::uuid, '9efc0547-9308-4f01-80b3-7a0a6da7b545'::uuid, 'true_false', 'Africa’s rate of urbanization is the highest in the world as stated in the excerpt.', 'True', 'The unit summary in the excerpt states that Africa’s rate of urbanization is the highest in the world.', 20),('119769f0-b38b-46d4-8047-7e1a466d5816'::uuid, '9efc0547-9308-4f01-80b3-7a0a6da7b545'::uuid, 'true_false', 'The three major components that bring about a change in population are fertility, mortality and migration.', 'True', 'The excerpt explicitly lists fertility, mortality, and migration as the three major components of population change.', 21),('ff53acae-7c69-444d-8e2d-845de1ccbd45'::uuid, '9efc0547-9308-4f01-80b3-7a0a6da7b545'::uuid, 'true_false', 'Most agriculture in Africa is rain-fed and therefore vulnerable to climate variability.', 'True', 'The excerpt notes that most agriculture in Africa is rain-fed and thus very vulnerable to climate variability such as droughts and floods.', 22),('aa32f512-bdbe-4621-832b-1a2543642a96'::uuid, '9efc0547-9308-4f01-80b3-7a0a6da7b545'::uuid, 'true_false', 'One of the Agenda 2063 flagship programs listed in the excerpt is "Silencing the guns by 2020."', 'True', 'The excerpt lists "Silencing the guns by 2020" among the Agenda 2063 flagship programs.', 23),('de802cd2-2c5a-4f46-86c9-24fa2598a530'::uuid, '9efc0547-9308-4f01-80b3-7a0a6da7b545'::uuid, 'fill_blank', 'Define population distribution as given in the excerpt.', 'Population distribution refers to the way people inhabit and occupy the earth’s surface.', 'The excerpt defines population distribution explicitly as the way people inhabit and occupy the earth’s surface.', 24),('6fa2b5b2-50f7-462e-8305-e724c2cb6401'::uuid, '9efc0547-9308-4f01-80b3-7a0a6da7b545'::uuid, 'fill_blank', 'Name two physical factors that determine spatial variation in the distribution of population in Africa mentioned in the excerpt.', 'Climate and availability of water.', 'The excerpt lists climate and availability of water among physical factors that influence population distribution.', 25),('958d79f6-af3f-4275-864a-6457db3d65cf'::uuid, '9efc0547-9308-4f01-80b3-7a0a6da7b545'::uuid, 'fill_blank', 'List two of the most densely populated countries in Africa as named in the excerpt.', 'Mauritius and Rwanda.', 'The excerpt names Mauritius and Rwanda among the continent’s most densely populated countries.', 26),('1c9459b8-bbe5-4f4e-87e2-a61d652885de'::uuid, '9efc0547-9308-4f01-80b3-7a0a6da7b545'::uuid, 'fill_blank', 'State one main feature of developing countries (DVCs) mentioned in the excerpt.', 'They are heavily committed to agriculture.', 'The excerpt describes developing countries as the world’s least industrialized nations that are heavily committed to agriculture.', 27),('0f9d456c-a6e6-4f28-8c37-143dba53f93f'::uuid, '9efc0547-9308-4f01-80b3-7a0a6da7b545'::uuid, 'fill_blank', 'Give two examples of activities included in the quaternary sector as described in the excerpt.', 'Information and communication technology (ICT) and research & development.', 'The excerpt lists ICT and research & development among quaternary sector activities based on knowledge and information generation.', 28),('799f499b-7cfa-4fe1-82e0-233bfd88240d'::uuid, '9efc0547-9308-4f01-80b3-7a0a6da7b545'::uuid, 'fill_blank', 'State the Brundtland Commission definition of sustainable development quoted in the excerpt.', '"Development that meets the needs of the present without compromising the ability of future generations to meet their own needs."', 'The excerpt quotes the Brundtland Commission definition verbatim as development meeting present needs without compromising future generations'' ability to meet theirs.', 29),('1a35dfbf-69f8-4b19-8074-0415b5d6c1e4'::uuid, '9efc0547-9308-4f01-80b3-7a0a6da7b545'::uuid, 'fill_blank', 'Name three flagship programs of Agenda 2063 listed in the excerpt.', 'Integrated high-speed train network; African passport and free movement of people; Implementation of the Grand Inga Dam project.', 'The excerpt lists these items among Agenda 2063 flagship programs including integrated trains, the African passport, and the Grand Inga Dam project.', 30),('0fc142bf-8350-4a9b-8c07-7a55351b66f6'::uuid, '9efc0547-9308-4f01-80b3-7a0a6da7b545'::uuid, 'fill_blank', 'Briefly explain why over-dependence on foreign aid can hinder economic growth according to the excerpt.', 'It causes stagnation because countries wait for aid instead of engaging in revenue-generating trade and investment activities.', 'The excerpt explains that relying on foreign aid can lead countries to postpone activities that generate revenue, thereby stagnating the economy.', 31),('7d6f16ca-20b2-48ac-89a7-1c4113d24aba'::uuid, '9efc0547-9308-4f01-80b3-7a0a6da7b545'::uuid, 'fill_blank', 'Using the excerpt figures that Africa has 624 million hectares of forest which comprise 20.6 percent of the continent’s land area, calculate the approximate land area of Africa in square kilometres.', '30,291,260 km2', 'Total land area = 624 million ha / 0.206 = 3,029.126 million ha = 30,291,260 km2 (1 ha = 0.01 km2); calculation uses values given in the excerpt.', 32),('91f32e35-6f44-4207-83d5-9e9696d6c650'::uuid, '9efc0547-9308-4f01-80b3-7a0a6da7b545'::uuid, 'fill_blank', 'If Africa’s population is about 1.3 billion and the average crude population density mid-2019 was about 44 people/km2 (both figures from the excerpt), estimate the continent’s land area in square kilometres.', '29,545,455 km2', 'Area ≈ population / density = 1,300,000,000 ÷ 44 ≈ 29,545,454.55 km2, rounded to 29,545,455 km2, using values provided in the excerpt.', 33),('935037c5-4009-4a1c-85d6-b430057c46c7'::uuid, '9efc0547-9308-4f01-80b3-7a0a6da7b545'::uuid, 'fill_blank', 'The excerpt states agriculture provides employment for about two-thirds of Africa’s working population. Express two-thirds as a percentage to one decimal place.', '66.7%', 'Two-thirds = 2/3 = 0.666... which equals 66.666...%, rounded to one decimal place is 66.7%.', 34),('38fba922-b73a-4082-8a97-3cecaedec924'::uuid, '9efc0547-9308-4f01-80b3-7a0a6da7b545'::uuid, 'fill_blank', 'Convert Africa’s forest area of 624 million hectares given in the excerpt into square kilometres.', '6,240,000 km2', '1 hectare = 0.01 km2, so 624 million ha × 0.01 = 6.24 million km2 = 6,240,000 km2, using the figure provided in the excerpt.', 35),('d98b5152-cadd-43f0-8f91-3d9e0acc5d37'::uuid, '9efc0547-9308-4f01-80b3-7a0a6da7b545'::uuid, 'fill_blank', 'Using Table 4.10 figures in the excerpt, what is the percentage point difference between the proportion of population in urban areas in Eastern Africa (26) and Southern Africa (62)?', '36 percentage points', 'Difference = 62% − 26% = 36 percentage points, directly using the table values provided in the excerpt.', 36),('af031dba-267c-4b5c-82da-4e0ed2833ba9'::uuid, '9efc0547-9308-4f01-80b3-7a0a6da7b545'::uuid, 'fill_blank', 'Using Table 4.9 values for Western Africa (65), Eastern Africa (65), and Sub-Saharan Africa (49), compute the average crude population density of these three regions.', '59.7 people/km2', 'Average = (65 + 65 + 49) ÷ 3 = 179 ÷ 3 ≈ 59.666..., rounded to one decimal place is 59.7 people/km2, using values from Table 4.9.', 37),('04ded1c7-a2e4-46e8-8bc2-b1f5dd97ec1f'::uuid, '9efc0547-9308-4f01-80b3-7a0a6da7b545'::uuid, 'fill_blank', 'What is the width of the range given for agriculture’s contribution to GDP in the excerpt when expressed in percentage points (30 to 60 percent)?', '30 percentage points', 'Range width = 60% − 30% = 30 percentage points, using the values explicitly stated in the excerpt.', 38),('eb45f929-2d31-427f-8a83-f8c57dfe6251'::uuid, '9efc0547-9308-4f01-80b3-7a0a6da7b545'::uuid, 'fill_blank', 'If Africa’s population is about 1.3 billion and the population in urban areas is currently estimated at 41% as given in the excerpt, approximately how many people live in urban areas?', '533,000,000 people', 'Urban population ≈ 1,300,000,000 × 0.41 = 533,000,000 people, using the population and 41% urban figure provided in the excerpt.', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
